mapper.select:
SELECT 
    ps.*,
    a.title as accommodation_title,
    img.image_url as accommodation_main_image_url,
    s.sido_name as sido_name,
    s.sido_img_url as sido_img_url
FROM popularity_stats ps
LEFT JOIN accommodations a ON ps.accommodation_id = a.accommodation_id
LEFT JOIN images img ON ps.accommodation_id = img.reference_id 
    AND img.reference_type = 'ACCOMMODATION' 
    AND img.is_main = true
LEFT JOIN sidos s ON ps.region_type = 'SIDO' AND ps.region_code = s.sido_code

    AND ps.stats_type = #{statsType}
    AND ps.region_type = #{regionType}
    AND ps.region_code = #{regionCode}
    AND ps.accommodation_id = #{accommodationId}
    AND ps.accommodation_type = #{accommodationType}
    AND ps.period_type = #{periodType}
    AND ps.period_value = #{periodValue}

        AND ps.period_value BETWEEN #{startDate} AND #{endDate}




    ORDER BY ${orderBy}


    LIMIT #{limit}


    OFFSET #{offset}

SELECT *
FROM popularity_stats
WHERE accommodation_id = #{accommodationId}
  AND period_type = #{periodType}
  AND period_value = #{periodValue}
  AND stats_type = 'ACCOMMODATION'
LIMIT 1
